package io.aetheris.orchestrator.career;import io.aetheris.orchestrator.github.*;import org.springframework.stereotype.Service;import java.util.*;@Service public class GitHubCareerEvidenceService {private final GitHubAdapterService github;public GitHubCareerEvidenceService(GitHubAdapterService github){this.github=github;}public GitHubCareerEvidenceResult inspect(GitHubCareerEvidenceRequest r){String path=r.path()==null||r.path().isBlank()?"README.md":r.path().trim();GitHubFileReadResult f=github.readFile(r.repository(),path,r.ref());String c=f.content()==null?"":f.content().toLowerCase(Locale.ROOT);List<String>e=new ArrayList<>(),g=new ArrayList<>();int score=0;score+=check(c,e,g,"installation","setup or installation instructions",15);score+=checkAny(c,e,g,List.of("test","testing","ci","github actions"),"testing/CI evidence",15);score+=checkAny(c,e,g,List.of("architecture","design","system design"),"architecture explanation",15);score+=checkAny(c,e,g,List.of("screenshot","demo","preview","video"),"visual/demo evidence",15);score+=checkAny(c,e,g,List.of("security","threat","permission"),"security thinking",10);score+=checkAny(c,e,g,List.of("docker","kubernetes","deployment","deploy"),"deployment/operations evidence",10);score+=checkAny(c,e,g,List.of("api","endpoint"),"API documentation",10);score+=Math.min(10,c.length()/800);return new GitHubCareerEvidenceResult(f.repository(),f.path(),f.ref(),f.sha(),f.htmlUrl(),f.content().length(),Math.min(100,score),e,g);}private int check(String c,List<String>e,List<String>g,String needle,String label,int points){if(c.contains(needle)){e.add(label);return points;}g.add("Missing or weak "+label);return 0;}private int checkAny(String c,List<String>e,List<String>g,List<String>needles,String label,int points){for(String n:needles)if(c.contains(n)){e.add(label);return points;}g.add("Missing or weak "+label);return 0;}}
